From db93de23fba0af4ce5ad0d1bc4abeb71b76cccf2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:22:52 +0100
Subject: [PATCH] kirigamiplasmastyle: update fonts when the application font
 changes

PlasmaTheme copied the application font once when it was created, so
Kirigami.Theme.defaultFont and smallFont kept the old size after a font
change until plasmashell restarted. Now they follow the app font.

BUG: 444629
---
 .../kirigamiplasmastyle/plasmatheme.cpp       | 48 +++++++++++++++----
 .../kirigamiplasmastyle/plasmatheme.h         |  1 +
 2 files changed, 41 insertions(+), 8 deletions(-)

diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
index eb317484e..ed14a3cb5 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
@@ -19,6 +19,31 @@
 #include <KConfigGroup>
 #include <KIconColors>

+class ApplicationFontWatcher : public QObject
+{
+    Q_OBJECT
+
+public:
+    ApplicationFontWatcher()
+    {
+        qGuiApp->installEventFilter(this);
+    }
+
+Q_SIGNALS:
+    void fontChanged();
+
+protected:
+    bool eventFilter(QObject *watched, QEvent *event) override
+    {
+        if (watched == qGuiApp && event->type() == QEvent::ApplicationFontChange) {
+            Q_EMIT fontChanged();
+        }
+        return false;
+    }
+};
+
+Q_GLOBAL_STATIC(ApplicationFontWatcher, s_fontWatcher)
+
 PlasmaTheme::PlasmaTheme(QObject *parent)
     : PlatformTheme(parent)
 {
@@ -36,6 +61,20 @@ PlasmaTheme::PlasmaTheme(QObject *parent)
         });
     }

+    syncFonts();
+    connect(s_fontWatcher, &ApplicationFontWatcher::fontChanged, this, &PlasmaTheme::syncFonts);
+
+    syncWindow();
+    syncColors();
+    connect(&m_theme, &Plasma::Theme::themeChanged, this, &PlasmaTheme::syncColors);
+}
+
+PlasmaTheme::~PlasmaTheme()
+{
+}
+
+void PlasmaTheme::syncFonts()
+{
     setDefaultFont(qGuiApp->font());

     KSharedConfigPtr ptr = KSharedConfig::openConfig();
@@ -52,14 +91,6 @@ PlasmaTheme::PlasmaTheme(QObject *parent)
 #endif
         return smallFont;
     }()));
-
-    syncWindow();
-    syncColors();
-    connect(&m_theme, &Plasma::Theme::themeChanged, this, &PlasmaTheme::syncColors);
-}
-
-PlasmaTheme::~PlasmaTheme()
-{
 }

 QIcon PlasmaTheme::iconFromTheme(const QString &name, const QColor &customColor)
@@ -210,3 +241,4 @@ bool PlasmaTheme::event(QEvent *event)
 }

 #include "moc_plasmatheme.cpp"
+#include "plasmatheme.moc"
diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
index 462c8713d..0cfa8c985 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
@@ -30,6 +30,7 @@ public:

     void syncWindow();
     void syncColors();
+    void syncFonts();
     void syncFrameContrast();

 protected:
